examples.code:
# Per-container override at run time:
$ docker run -d --log-opt max-size=10m --log-opt max-file=3 --name web myapp

# Daemon-wide default so every future container gets this unless it overrides it:
# /etc/docker/daemon.json
{
  "log-driver": "json-file",
  "log-opts": {
    "max-size": "10m",
    "max-file": "3"
  }
}
# then: sudo systemctl restart docker

exercises.solutionCode:
# Stop and remove the current container, then restart it with bounded logging:
$ docker rm -f flaky-worker
$ docker run -d --name flaky-worker --log-opt max-size=10m --log-opt max-file=3 myworker:2.1

# And, to prevent any OTHER container on this host from doing the same thing,
# set a host-wide default in /etc/docker/daemon.json:
{
  "log-driver": "json-file",
  "log-opts": { "max-size": "10m", "max-file": "3" }
}
# then: sudo systemctl restart docker
